<?php
declare(strict_types=1);
use App\Domain\Services\PricingEngine; use App\Shared\Exceptions\ApiException; use PHPUnit\Framework\TestCase;
final class PricingEngineTest extends TestCase { private array $sku=['public_id'=>'sku_x','minimum_order_quantity'=>5,'reference_unit_price'=>285000,'pricing_version'=>2]; private array $tiers=[['min_quantity'=>5,'max_quantity'=>9,'unit_price'=>285000],['min_quantity'=>10,'max_quantity'=>24,'unit_price'=>245000],['min_quantity'=>25,'max_quantity'=>49,'unit_price'=>230000],['min_quantity'=>50,'max_quantity'=>null,'unit_price'=>220000]]; public function boundaries():array{return [[5,285000],[9,285000],[10,245000],[24,245000],[25,230000],[49,230000],[50,220000]];} /** @dataProvider boundaries */ public function testTierBoundaries(int $q,int $price):void{$got=(new PricingEngine())->quote($this->sku,$this->tiers,$q,100);self::assertSame($price,$got['unitPrice']);self::assertSame($price*$q,$got['lineSubtotal']);} public function testMinimumIsEnforced():void{$this->expectException(ApiException::class);(new PricingEngine())->quote($this->sku,$this->tiers,4,100);} public function testStockIsEnforced():void{$this->expectException(ApiException::class);(new PricingEngine())->quote($this->sku,$this->tiers,50,49);} }
